import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Token 与上下文窗口","description":"理解分词、词表、Token ID、特殊 Token、上下文组成、输入输出预算、截断和精确计数边界。","frontmatter":{"title":"Token 与上下文窗口","description":"理解分词、词表、Token ID、特殊 Token、上下文组成、输入输出预算、截断和精确计数边界。","verified_at":"2026-07-28","sources":["https://huggingface.co/docs/tokenizers/index","https://huggingface.co/docs/transformers/main/en/tokenizer_summary","https://web.stanford.edu/~jurafsky/slp3/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/tokens-context-window.md","filePath":"py-agent/foundations/model-principles/tokens-context-window.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/tokens-context-window.md"};function r(d,e,l,s,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="token-与上下文窗口" tabindex="-1">Token 与上下文窗口 <a class="header-anchor" href="#token-与上下文窗口" aria-label="Permalink to &quot;Token 与上下文窗口&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>模型不会直接接收“字符”或“单词”。文本先经过与模型配套的分词器，被转换成有限词表中的 Token ID；模型再在有限的上下文窗口中处理这些 ID。Token 是文本接口与模型数值计算之间的边界，也决定请求容量、生成上限、延迟和部分成本。</p><h2 id="_1-字符、单词与-token" tabindex="-1">1. 字符、单词与 Token <a class="header-anchor" href="#_1-字符、单词与-token" aria-label="Permalink to &quot;1. 字符、单词与 Token&quot;">​</a></h2><h3 id="_1-1-三种单位不能互换" tabindex="-1">1.1 三种单位不能互换 <a class="header-anchor" href="#_1-1-三种单位不能互换" aria-label="Permalink to &quot;1.1 三种单位不能互换&quot;">​</a></h3><table tabindex="0"><thead><tr><th>单位</th><th>例子</th><th>边界由谁决定</th></tr></thead><tbody><tr><td>字符</td><td><code>P</code>、<code>猫</code>、<code>。</code></td><td>Unicode 文本表示</td></tr><tr><td>单词</td><td><code>playing</code>、中文分词中的“模型”</td><td>语言和分析规则</td></tr><tr><td>Token</td><td><code>play</code> + <code>ing</code>，或其他切分</td><td>具体模型的分词器和词表</td></tr></tbody></table><p>一个 Token 可能是完整单词、词的一部分、标点、空白组合、汉字或字节片段。英文里的常见词可能只有一个 Token，生僻词可能拆成多个；中文也不能假设“一字一 Token”。</p><h3 id="_1-2-为什么不直接按单词建词表" tabindex="-1">1.2 为什么不直接按单词建词表 <a class="header-anchor" href="#_1-2-为什么不直接按单词建词表" aria-label="Permalink to &quot;1.2 为什么不直接按单词建词表&quot;">​</a></h3><p>只收录完整单词会遇到未登录词、拼写变化、代码标识符和多语言词汇爆炸；只按字符或字节处理又会让序列变长。现代分词器通常在词表大小与序列长度之间折中，学习可复用的子词或字节级片段。</p><h3 id="_1-3-空格和大小写也可能改变结果" tabindex="-1">1.3 空格和大小写也可能改变结果 <a class="header-anchor" href="#_1-3-空格和大小写也可能改变结果" aria-label="Permalink to &quot;1.3 空格和大小写也可能改变结果&quot;">​</a></h3><p><code>agent</code>、<code> Agent</code> 和 <code>AGENT</code> 可能得到不同 Token 序列。标点、换行、Unicode 规范化、代码缩进也会影响切分。不能用字符串长度或肉眼单词数精确推算 Token 数。</p><h2 id="_2-分词器与词表" tabindex="-1">2. 分词器与词表 <a class="header-anchor" href="#_2-分词器与词表" aria-label="Permalink to &quot;2. 分词器与词表&quot;">​</a></h2><h3 id="_2-1-分词器执行双向映射" tabindex="-1">2.1 分词器执行双向映射 <a class="header-anchor" href="#_2-1-分词器执行双向映射" aria-label="Permalink to &quot;2.1 分词器执行双向映射&quot;">​</a></h3><p>编码把文本变为 Token 和对应 ID：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;unbelievable&quot;</span></span>
<span class="line"><span>  -&gt; [&quot;un&quot;, &quot;believ&quot;, &quot;able&quot;]       # 仅为示意</span></span>
<span class="line"><span>  -&gt; [438, 9127, 611]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>解码把 ID 序列还原为文本。中间 Token 边界是模型词表的产物，不应被应用当作稳定的语言学边界。</p><h3 id="_2-2-token-id-只在特定词表内有意义" tabindex="-1">2.2 Token ID 只在特定词表内有意义 <a class="header-anchor" href="#_2-2-token-id-只在特定词表内有意义" aria-label="Permalink to &quot;2.2 Token ID 只在特定词表内有意义&quot;">​</a></h3><p>ID 本质上是词表索引。不同模型或不同版本的分词器可能让同一 ID 对应完全不同的 Token，也可能对同一文本产生不同长度的序列。存储 Token ID 作为长期跨模型数据格式通常是不可靠的，应保留原始文本和明确的分词器版本。</p><h3 id="_2-3-编码必须与模型匹配" tabindex="-1">2.3 编码必须与模型匹配 <a class="header-anchor" href="#_2-3-编码必须与模型匹配" aria-label="Permalink to &quot;2.3 编码必须与模型匹配&quot;">​</a></h3><p>模型的输入 Embedding 矩阵按训练时词表排列。若用错误分词器产生 ID，即使 ID 数值合法，也会索引到错误向量。模型服务通常在服务端完成分词；本地计数工具也必须选择与目标模型匹配的编码。</p><h2 id="_3-特殊-token-与消息序列化" tabindex="-1">3. 特殊 Token 与消息序列化 <a class="header-anchor" href="#_3-特殊-token-与消息序列化" aria-label="Permalink to &quot;3. 特殊 Token 与消息序列化&quot;">​</a></h2><h3 id="_3-1-特殊-token-表达结构" tabindex="-1">3.1 特殊 Token 表达结构 <a class="header-anchor" href="#_3-1-特殊-token-表达结构" aria-label="Permalink to &quot;3.1 特殊 Token 表达结构&quot;">​</a></h3><p>模型可能使用特殊 Token 表示序列开始、序列结束、消息边界、角色或填充位置。这些 Token 不一定对应用户可见字符，却占用模型处理的序列位置。</p><h3 id="_3-2-聊天消息最终仍会变成序列" tabindex="-1">3.2 聊天消息最终仍会变成序列 <a class="header-anchor" href="#_3-2-聊天消息最终仍会变成序列" aria-label="Permalink to &quot;3.2 聊天消息最终仍会变成序列&quot;">​</a></h3><p>应用看到的 <code>system</code>、<code>user</code>、<code>assistant</code> 等消息是 API 层结构。服务会按模型的聊天模板加入角色和边界标记，再编码成 Token。因而：</p><ul><li>消息元数据可能产生额外 Token。</li><li>相同可见文字放在不同角色中，最终序列不同。</li><li>不应自行猜测供应商的隐藏模板开销。</li></ul><p>消息层级的语义属于下一分组，本章只说明它最终受同一上下文窗口约束。</p><h3 id="_3-3-用户文本不能伪造真正的结构边界" tabindex="-1">3.3 用户文本不能伪造真正的结构边界 <a class="header-anchor" href="#_3-3-用户文本不能伪造真正的结构边界" aria-label="Permalink to &quot;3.3 用户文本不能伪造真正的结构边界&quot;">​</a></h3><p>在普通字符串里写“system:”通常仍是用户内容，不会自动变成高优先级系统消息。结构必须通过 API 的消息字段表达，并由服务按模型协议序列化。</p><h2 id="_4-上下文窗口" tabindex="-1">4. 上下文窗口 <a class="header-anchor" href="#_4-上下文窗口" aria-label="Permalink to &quot;4. 上下文窗口&quot;">​</a></h2><h3 id="_4-1-窗口是一次推理可处理的-token-范围" tabindex="-1">4.1 窗口是一次推理可处理的 Token 范围 <a class="header-anchor" href="#_4-1-窗口是一次推理可处理的-token-范围" aria-label="Permalink to &quot;4.1 窗口是一次推理可处理的 Token 范围&quot;">​</a></h3><p>上下文窗口通常容纳当前请求的输入 Token 和模型在该请求中生成的输出 Token。概念上可写为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 Token 数 + 可生成输出 Token 数 &lt;= 模型上下文上限</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>具体服务可能为内部推理、工具描述或特殊控制信息保留预算，供应商参数名和计算方式也可能不同。应用必须以目标模型当前文档和实际用量字段为准。</p><h3 id="_4-2-输入不只是用户最后一句话" tabindex="-1">4.2 输入不只是用户最后一句话 <a class="header-anchor" href="#_4-2-输入不只是用户最后一句话" aria-label="Permalink to &quot;4.2 输入不只是用户最后一句话&quot;">​</a></h3><p>一次模型调用的输入可能包括：</p><ol><li>系统或开发者指令。</li><li>对话历史。</li><li>当前用户消息。</li><li>工具定义或输出 Schema。</li><li>检索文档和工具结果。</li><li>消息模板与特殊 Token 开销。</li></ol><p>只统计当前问题会严重低估真实上下文。</p><h3 id="_4-3-窗口大不等于所有信息利用得同样好" tabindex="-1">4.3 窗口大不等于所有信息利用得同样好 <a class="header-anchor" href="#_4-3-窗口大不等于所有信息利用得同样好" aria-label="Permalink to &quot;4.3 窗口大不等于所有信息利用得同样好&quot;">​</a></h3><p>模型能接收某个长度，不表示它对窗口内每个位置都同样敏感。过多无关内容会稀释任务信号，关键证据也可能因位置、冲突或长距离依赖而没有被正确使用。容量是硬边界，信息利用质量是另一项需要评测的能力。</p><h2 id="_5-输入与输出预算" tabindex="-1">5. 输入与输出预算 <a class="header-anchor" href="#_5-输入与输出预算" aria-label="Permalink to &quot;5. 输入与输出预算&quot;">​</a></h2><h3 id="_5-1-先为输出保留空间" tabindex="-1">5.1 先为输出保留空间 <a class="header-anchor" href="#_5-1-先为输出保留空间" aria-label="Permalink to &quot;5.1 先为输出保留空间&quot;">​</a></h3><p>如果模型上限是 <code>W</code>，预计输入是 <code>I</code>，还应为输出、结构标记和安全余量预留 <code>O</code> 与 <code>M</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I + O + M &lt;= W</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>把窗口全部塞满输入，可能导致没有足够空间完成 JSON、代码块或长答案。输出被截断时，结构化结果尤其容易变成无效 JSON。</p><h3 id="_5-2-输出上限是上限-不是目标长度" tabindex="-1">5.2 输出上限是上限，不是目标长度 <a class="header-anchor" href="#_5-2-输出上限是上限-不是目标长度" aria-label="Permalink to &quot;5.2 输出上限是上限，不是目标长度&quot;">​</a></h3><p>允许最多生成 2,000 Token 不代表模型一定生成这么多。模型可能遇到结束 Token、停止字符串、任务完成条件或服务限制而提前结束。反之，上限过小会机械截断尚未完成的内容。</p><h3 id="_5-3-token-数也影响延迟" tabindex="-1">5.3 Token 数也影响延迟 <a class="header-anchor" href="#_5-3-token-数也影响延迟" aria-label="Permalink to &quot;5.3 Token 数也影响延迟&quot;">​</a></h3><p>处理输入的阶段通常随输入长度增加而变慢；自回归输出又要逐 Token 生成，长输出直接增加用户等待时间。缓存和推理优化会改变具体曲线，但“更长上下文与输出不是免费的”是稳定边界。</p><h2 id="_6-超限与截断" tabindex="-1">6. 超限与截断 <a class="header-anchor" href="#_6-超限与截断" aria-label="Permalink to &quot;6. 超限与截断&quot;">​</a></h2><h3 id="_6-1-超限可能被拒绝或截断" tabindex="-1">6.1 超限可能被拒绝或截断 <a class="header-anchor" href="#_6-1-超限可能被拒绝或截断" aria-label="Permalink to &quot;6.1 超限可能被拒绝或截断&quot;">​</a></h3><p>不同 API 可能直接返回上下文超限错误，也可能由 SDK、框架或应用先截断。静默截断最危险，因为请求仍可能成功，但关键约束或证据已经消失。</p><h3 id="_6-2-不能机械删除最早消息" tabindex="-1">6.2 不能机械删除最早消息 <a class="header-anchor" href="#_6-2-不能机械删除最早消息" aria-label="Permalink to &quot;6.2 不能机械删除最早消息&quot;">​</a></h3><p>最早消息可能包含系统约束、用户偏好或尚未解决的任务条件。合理压缩需要按信息职责处理：</p><table tabindex="0"><thead><tr><th>内容</th><th>常见策略</th></tr></thead><tbody><tr><td>高优先级规则</td><td>保留原文或稳定结构化表示</td></tr><tr><td>已完成对话细节</td><td>摘要后保留必要状态</td></tr><tr><td>可再次获取的工具结果</td><td>保留标识，按需重新查询</td></tr><tr><td>大段参考资料</td><td>检索相关片段，而非全部拼接</td></tr><tr><td>重复内容</td><td>去重并保留权威版本</td></tr></tbody></table><p>摘要本身也可能丢失信息，因此摘要字段和原始记录的关系应可追踪。</p><h3 id="_6-3-截断必须从完整语义单位发生" tabindex="-1">6.3 截断必须从完整语义单位发生 <a class="header-anchor" href="#_6-3-截断必须从完整语义单位发生" aria-label="Permalink to &quot;6.3 截断必须从完整语义单位发生&quot;">​</a></h3><p>任意切掉字符串尾部可能破坏 JSON、代码、表格或一个关键否定句。应用应尽量按消息、文档段落或数据记录等完整单位裁剪，并在裁剪后重新计算 Token。</p><h2 id="_7-token-计数方法" tabindex="-1">7. Token 计数方法 <a class="header-anchor" href="#_7-token-计数方法" aria-label="Permalink to &quot;7. Token 计数方法&quot;">​</a></h2><h3 id="_7-1-精确计数依赖具体模型协议" tabindex="-1">7.1 精确计数依赖具体模型协议 <a class="header-anchor" href="#_7-1-精确计数依赖具体模型协议" aria-label="Permalink to &quot;7.1 精确计数依赖具体模型协议&quot;">​</a></h3><p>最可靠的方法是使用目标模型官方提供或指定的 tokenizer，并把消息模板、工具定义等协议开销纳入计算。服务返回的实际 usage 是最终计量事实，但它只能在调用后获得。</p><h3 id="_7-2-估算只适合容量预警" tabindex="-1">7.2 估算只适合容量预警 <a class="header-anchor" href="#_7-2-估算只适合容量预警" aria-label="Permalink to &quot;7.2 估算只适合容量预警&quot;">​</a></h3><p>按字符或单词比例估算可以做 UI 预警和粗略分桶，不能用于紧贴硬上限的请求。语言、代码、数字和空白格式都会让比例变化。</p><h3 id="_7-3-记录原始用量" tabindex="-1">7.3 记录原始用量 <a class="header-anchor" href="#_7-3-记录原始用量" aria-label="Permalink to &quot;7.3 记录原始用量&quot;">​</a></h3><p>生产应用至少应记录模型标识、输入 Token、输出 Token、是否截断和完成状态。只记录总 Token 会掩盖“输入膨胀”与“输出失控”这两类不同问题。</p><h2 id="_8-常见误解" tabindex="-1">8. 常见误解 <a class="header-anchor" href="#_8-常见误解" aria-label="Permalink to &quot;8. 常见误解&quot;">​</a></h2><h3 id="_8-1-一个-token-就是一个单词" tabindex="-1">8.1 “一个 Token 就是一个单词” <a class="header-anchor" href="#_8-1-一个-token-就是一个单词" aria-label="Permalink to &quot;8.1 “一个 Token 就是一个单词”&quot;">​</a></h3><p>Token 是分词器单位。它可能小于、等于或大于语言学意义上的单词片段。</p><h3 id="_8-2-上下文窗口就是聊天记录长度" tabindex="-1">8.2 “上下文窗口就是聊天记录长度” <a class="header-anchor" href="#_8-2-上下文窗口就是聊天记录长度" aria-label="Permalink to &quot;8.2 “上下文窗口就是聊天记录长度”&quot;">​</a></h3><p>窗口还包括指令、工具、检索材料、当前消息、输出预算和协议开销。</p><h3 id="_8-3-支持长上下文就应该把所有资料都传入" tabindex="-1">8.3 “支持长上下文就应该把所有资料都传入” <a class="header-anchor" href="#_8-3-支持长上下文就应该把所有资料都传入" aria-label="Permalink to &quot;8.3 “支持长上下文就应该把所有资料都传入”&quot;">​</a></h3><p>无关信息会增加成本和干扰。应根据任务选择、压缩和标明证据，而不是把窗口容量当作内容质量。</p><h2 id="_9-自测" tabindex="-1">9. 自测 <a class="header-anchor" href="#_9-自测" aria-label="Permalink to &quot;9. 自测&quot;">​</a></h2><ol><li>为什么 Token 不能等同于字符或单词？</li><li>Token ID 为什么不能脱离具体词表解释？</li><li>聊天 API 中哪些内容会占用上下文？</li><li>为什么必须在装入输入前预留输出预算？</li><li>静默截断会造成哪些比显式报错更难发现的问题？</li></ol><p>能够从“原始文本 → 聊天模板 → Token → Token ID → 输入与输出预算”完整解释请求容量，就掌握了模型文本边界。</p>`,75)])])}const u=a(i,[["render",r]]);export{k as __pageData,u as default};
